using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections.Generic;
using System.Security.Cryptography;
using System.Text.RegularExpressions;

public interface ISceneBlockRegistryStore { string GetCommand(); void SetCommand(string command); bool DeleteOwnedCommand(string expectedCommand); }
public class SceneBlockVersionInfo {
 public string Version,DirectoryPath; public bool Recognized,Busy,Registered,Complete,ResidualOnly,ProgramFilesPresent;
 public List<string> PreservedReasons=new List<string>();
 internal Dictionary<string,string> Owned=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
}
public class SceneBlockPlannedFile { public string Path,ExpectedHash; }
public class SceneBlockRemovalPlan {
 public bool OldOnly,WillRemoveRegistration,CanExecute; public string RegistrySnapshot;
 public List<SceneBlockPlannedFile> Files=new List<SceneBlockPlannedFile>();
 public List<string> Directories=new List<string>(),PreservedReasons=new List<string>(),BlockedReasons=new List<string>();
 internal string Snapshot,Seal; internal SceneBlockInstallationManager Owner;
}
public class SceneBlockRemovalResult {
 public bool Success,Partial; public List<string> RemovedFiles=new List<string>(),PreservedReasons=new List<string>(),Errors=new List<string>();
}
public class SceneBlockInstallationManager {
 public const string ManifestName="2026-10-25-SceneBlock-ownership-v1.txt";
 readonly string root,currentVersion; readonly Func<string,bool> isBusy; readonly ISceneBlockRegistryStore registry;
 readonly Dictionary<string,Dictionary<string,string>> trusted;
 readonly string[] critical={"node.exe","2026-10-23-protocol.vbs","2026-10-23-on-demand.mjs"};
 public SceneBlockInstallationManager(string root,string currentVersion,Func<string,bool> isBusy,ISceneBlockRegistryStore registry,Dictionary<string,Dictionary<string,string>> trustedLegacyHashes){
  this.root=System.IO.Path.GetFullPath(root).TrimEnd(System.IO.Path.DirectorySeparatorChar);ValidateVersion(currentVersion);this.currentVersion=currentVersion;this.isBusy=isBusy??delegate{return true;};this.registry=registry;trusted=trustedLegacyHashes??new Dictionary<string,Dictionary<string,string>>();Safe(this.root);
 }
 static void ValidateVersion(string version){if(version==null||!Regex.IsMatch(version,@"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$"))throw new InvalidOperationException("Invalid installation version");}
 bool OlderThanCurrent(string version){ValidateVersion(version);string[] candidate=version.Split('.'),current=currentVersion.Split('.');for(int i=0;i<3;i++){if(candidate[i].Length!=current[i].Length)return candidate[i].Length<current[i].Length;int difference=String.CompareOrdinal(candidate[i],current[i]);if(difference!=0)return difference<0;}return false;}
 string Folder(string version){ValidateVersion(version);string p=System.IO.Path.Combine(root,version);Safe(p);return p;}
 void Safe(string path){string full=System.IO.Path.GetFullPath(path);if(full!=root&&!full.StartsWith(root+System.IO.Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Outside installation root");for(string p=full;p!=null;p=System.IO.Path.GetDirectoryName(p)){if((File.Exists(p)||Directory.Exists(p))&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("Reparse point refused: "+p);}}
 static bool Name(string name){return !String.IsNullOrEmpty(name)&&name==System.IO.Path.GetFileName(name)&&name.IndexOfAny(new[]{'/', '\\',':','\r','\n','|'})<0&&name!="."&&name!="..";}
 static string Hash(string file){using(var sha=SHA256.Create())using(var stream=File.OpenRead(file))return BitConverter.ToString(sha.ComputeHash(stream)).Replace("-","").ToLowerInvariant();}
 public string BuildCommand(string version){return "\""+System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),"System32","wscript.exe")+"\" \""+System.IO.Path.Combine(Folder(version),"2026-10-23-protocol.vbs")+"\" \"%1\"";}
 Dictionary<string,string> Ownership(string version){string folder=Folder(version),manifest=System.IO.Path.Combine(folder,ManifestName);var owned=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  if(File.Exists(manifest)){Safe(manifest);string[] lines=File.ReadAllLines(manifest);if(lines.Length<2||lines[0]!="SceneBlock ownership v1"||lines[1]!="Version="+version)throw new InvalidOperationException("Invalid ownership manifest");foreach(string line in lines.Skip(2)){string[] parts=line.Split('|');if(parts.Length!=2||!Name(parts[0])||parts[0].Equals(ManifestName,StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(parts[1],"^[a-fA-F0-9]{64}$")||owned.ContainsKey(parts[0]))throw new InvalidOperationException("Unsafe ownership manifest");owned.Add(parts[0],parts[1].ToLowerInvariant());}owned.Add(ManifestName,Hash(manifest));return owned;}
  Dictionary<string,string> legacy;foreach(string n in critical)Safe(System.IO.Path.Combine(folder,n));if(trusted.TryGetValue(version,out legacy)&&legacy.Any(pair=>(pair.Key.EndsWith(".mjs",StringComparison.OrdinalIgnoreCase)||pair.Key.EndsWith(".vbs",StringComparison.OrdinalIgnoreCase)||pair.Key.EndsWith(".ps1",StringComparison.OrdinalIgnoreCase))&&Name(pair.Key)&&File.Exists(System.IO.Path.Combine(folder,pair.Key))&&Hash(System.IO.Path.Combine(folder,pair.Key)).Equals(pair.Value,StringComparison.OrdinalIgnoreCase))){foreach(var pair in legacy){if(!Name(pair.Key)||!Regex.IsMatch(pair.Value,"^[a-fA-F0-9]{64}$"))throw new InvalidOperationException("Unsafe legacy fingerprint");owned.Add(pair.Key,pair.Value.ToLowerInvariant());}}return owned;
 }
 void Classify(SceneBlockVersionInfo info){string[] files=Directory.GetFiles(info.DirectoryPath),dirs=Directory.GetDirectories(info.DirectoryPath);foreach(string p in files.Concat(dirs))Safe(p);Dictionary<string,string> known;bool trustedVersion=trusted.TryGetValue(info.Version,out known);info.ProgramFilesPresent=files.Any(p=>critical.Contains(System.IO.Path.GetFileName(p),StringComparer.OrdinalIgnoreCase)||(trustedVersion&&known.ContainsKey(System.IO.Path.GetFileName(p)))||new[]{".exe",".mjs",".vbs",".ps1",".dll"}.Contains(System.IO.Path.GetExtension(p),StringComparer.OrdinalIgnoreCase));info.ResidualOnly=(trustedVersion||info.Recognized)&&!info.ProgramFilesPresent&&!info.Registered&&files.All(p=>System.IO.Path.GetFileName(p)==ManifestName||Regex.IsMatch(System.IO.Path.GetFileName(p),@"^2026-10-25-previous-protocol-\d+\.txt$"))&&dirs.All(p=>System.IO.Path.GetFileName(p)=="2026-10-23-runtime");}
 public static string StatusText(SceneBlockVersionInfo info){if(info.Complete)return "설치됨 · 정상";if(info.Busy)return "검사 실패 또는 사용 중 · 보존";if(info.ResidualOnly)return "프로그램 파일 없음 · 로그/설정 잔여";if(info.Registered&&!info.ProgramFilesPresent)return "웹 연결 등록 남음 · 프로그램 파일 없음";if(info.Recognized)return "일부 프로그램 파일 남음 · 정리 가능";if(info.ProgramFilesPresent)return "프로그램 파일 남음 · 소유권 미확인 / 보존";return "미확인 잔여 항목 · 보존";}
 public List<SceneBlockVersionInfo> Scan(){Safe(root);var infos=new List<SceneBlockVersionInfo>();if(!Directory.Exists(root))return infos;string command=registry.GetCommand();foreach(string folder in Directory.GetDirectories(root).OrderBy(p=>p,StringComparer.OrdinalIgnoreCase)){string version=System.IO.Path.GetFileName(folder);if(!Regex.IsMatch(version,@"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)$"))continue;var info=new SceneBlockVersionInfo{Version=version,DirectoryPath=folder};try{Safe(folder);info.Owned=Ownership(version);info.Recognized=info.Owned.Count>0;foreach(string name in info.Owned.Keys)Safe(System.IO.Path.Combine(folder,name));info.Registered=command==BuildCommand(version);info.Busy=isBusy(version);Classify(info);info.Complete=info.Recognized&&critical.All(n=>info.Owned.ContainsKey(n))&&info.Owned.All(entry=>File.Exists(System.IO.Path.Combine(folder,entry.Key))&&Hash(System.IO.Path.Combine(folder,entry.Key))==entry.Value);if(info.ResidualOnly)info.PreservedReasons.Add("프로그램 파일 없음 · 로그/설정 잔여 보존: "+folder);else if(!info.Recognized)info.PreservedReasons.Add("소유권 미확인 항목 보존: "+folder);}catch(Exception e){info.Busy=true;info.Complete=false;info.PreservedReasons.Add("Detection failed; preserve installation: "+e.Message);}infos.Add(info);}return infos;}
 public void RecordManifest(string version,Dictionary<string,string> payloadHashes){string folder=Folder(version);if(payloadHashes==null||!critical.All(n=>payloadHashes.ContainsKey(n)))throw new InvalidOperationException("Critical payload hashes required");var lines=new List<string>{"SceneBlock ownership v1","Version="+version};foreach(var pair in payloadHashes.OrderBy(p=>p.Key,StringComparer.OrdinalIgnoreCase)){if(!Name(pair.Key)||pair.Key.Equals(ManifestName,StringComparison.OrdinalIgnoreCase)||!Regex.IsMatch(pair.Value,"^[a-fA-F0-9]{64}$"))throw new InvalidOperationException("Invalid payload entry");string file=System.IO.Path.Combine(folder,pair.Key);Safe(file);if(!File.Exists(file)||!Hash(file).Equals(pair.Value,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Payload mismatch: "+file);lines.Add(pair.Key+"|"+pair.Value.ToLowerInvariant());}string text=String.Join("\n",lines)+"\n",manifest=System.IO.Path.Combine(folder,ManifestName);Safe(manifest);if(File.Exists(manifest)){if(File.ReadAllText(manifest)!=text)throw new InvalidOperationException("Existing ownership manifest preserved");return;}using(var stream=new FileStream(manifest,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))writer.Write(text);}
 string Snapshot(bool oldOnly){var entries=new List<string>();Safe(root);if(!Directory.Exists(root))return "";foreach(var info in Scan()){Safe(info.DirectoryPath);if(!info.Recognized||(oldOnly&&(!OlderThanCurrent(info.Version)||info.Registered)))continue;entries.Add("D|"+info.DirectoryPath);foreach(string file in Directory.GetFiles(info.DirectoryPath).OrderBy(p=>p,StringComparer.OrdinalIgnoreCase)){Safe(file);entries.Add("F|"+file+"|"+Hash(file));}foreach(string directory in Directory.GetDirectories(info.DirectoryPath).OrderBy(p=>p,StringComparer.OrdinalIgnoreCase)){Safe(directory);entries.Add("P|"+directory+"|"+File.GetAttributes(directory));}}return String.Join("\n",entries);}
 string Seal(SceneBlockRemovalPlan plan){return plan.OldOnly+"|"+plan.RegistrySnapshot+"|"+plan.WillRemoveRegistration+"|"+String.Join("\n",plan.Files.Select(f=>f.Path+"|"+f.ExpectedHash))+"|"+String.Join("\n",plan.Directories);}
 public SceneBlockRemovalPlan PlanRemoval(bool oldOnly){var plan=new SceneBlockRemovalPlan{OldOnly=oldOnly,RegistrySnapshot=registry.GetCommand(),Owner=this};try{plan.Snapshot=Snapshot(oldOnly);foreach(var info in Scan()){if(oldOnly&&(!OlderThanCurrent(info.Version)||info.Registered)){plan.PreservedReasons.Add("Retained current, newer or registered version: "+info.Version);continue;}if(!info.Recognized){plan.PreservedReasons.AddRange(info.PreservedReasons);continue;}if(info.Busy)plan.BlockedReasons.Add("Installation is busy: "+info.Version);plan.Directories.Add(info.DirectoryPath);foreach(string file in Directory.GetFiles(info.DirectoryPath)){Safe(file);string name=System.IO.Path.GetFileName(file),expected;if(info.Owned.TryGetValue(name,out expected)&&Hash(file).Equals(expected,StringComparison.OrdinalIgnoreCase))plan.Files.Add(new SceneBlockPlannedFile{Path=file,ExpectedHash=expected});else plan.PreservedReasons.Add("Unknown or modified file: "+file);}foreach(string dir in Directory.GetDirectories(info.DirectoryPath))plan.PreservedReasons.Add("Runtime or unknown directory: "+dir);if(!oldOnly&&info.Registered)plan.WillRemoveRegistration=true;}plan.CanExecute=plan.BlockedReasons.Count==0;plan.Seal=Seal(plan);}catch(Exception e){plan.BlockedReasons.Add(e.Message);plan.CanExecute=false;}return plan;}
 public SceneBlockRemovalResult Remove(SceneBlockRemovalPlan plan){var result=new SceneBlockRemovalResult();try{if(plan==null||plan.Owner!=this||!plan.CanExecute||plan.BlockedReasons.Count>0||plan.Seal!=Seal(plan))throw new InvalidOperationException("Invalid or blocked removal plan");if(registry.GetCommand()!=plan.RegistrySnapshot||Snapshot(plan.OldOnly)!=plan.Snapshot)throw new InvalidOperationException("Installation or registration changed; preview again");var fresh=PlanRemoval(plan.OldOnly);if(!fresh.CanExecute||fresh.Seal!=plan.Seal)throw new InvalidOperationException("Installation changed or busy; preview again");foreach(var file in plan.Files){Safe(file.Path);if(!File.Exists(file.Path)||Hash(file.Path)!=file.ExpectedHash)throw new InvalidOperationException("File changed; preview again");}if(plan.WillRemoveRegistration&&!registry.DeleteOwnedCommand(plan.RegistrySnapshot))throw new InvalidOperationException("Registration changed; preserved");foreach(var file in plan.Files.OrderBy(f=>System.IO.Path.GetFileName(f.Path)==ManifestName?1:0)){try{if(System.IO.Path.GetFileName(file.Path)==ManifestName&&result.Errors.Count>0){result.PreservedReasons.Add("Ownership manifest retained after deletion error: "+file.Path);continue;}Safe(file.Path);if(Hash(file.Path)!=file.ExpectedHash)throw new InvalidOperationException("File changed: "+file.Path);File.Delete(file.Path);result.RemovedFiles.Add(file.Path);}catch(Exception e){result.Errors.Add(e.Message);}}foreach(string dir in plan.Directories){Safe(dir);if(Directory.Exists(dir)&&Directory.GetFileSystemEntries(dir).Length==0)Directory.Delete(dir,false);}result.PreservedReasons.AddRange(plan.PreservedReasons);result.Partial=result.Errors.Count>0||plan.Directories.Any(Directory.Exists);result.Success=result.Errors.Count==0&&!result.Partial;}catch(Exception e){result.Errors.Add(e.Message);result.Partial=result.RemovedFiles.Count>0;}return result;}
 public bool Repair(string version){var info=Scan().FirstOrDefault(v=>v.Version==version);if(info==null||!info.Complete||info.Busy)throw new InvalidOperationException("Repair requires a complete idle owned installation");string before=registry.GetCommand();if(!String.IsNullOrEmpty(before)&&!Scan().Any(v=>v.Recognized&&before==BuildCommand(v.Version)))throw new InvalidOperationException("Foreign registration preserved");Safe(Folder(version));if(registry.GetCommand()!=before)throw new InvalidOperationException("Registration changed");registry.SetCommand(BuildCommand(version));return true;}
}
